using System;
using System.Linq;
using LastRail.Auth;
using Newtonsoft.Json.Linq;
namespace LastRail.Presentation.MissionShell {
 public sealed class ObjectiveProgress {
  readonly JObject data;
  public long ServerTime=>(long)data["serverTime"];
  public JObject SystemState(string system)=>data["systems"].FirstOrDefault(s=>(string)s["system"]==system)?.DeepClone() as JObject;
  public ObjectiveProgress(JObject input){data=(JObject)input.DeepClone();if(GameApiJson.String(data,"version")!="objective-progress-v1")throw new FormatException();var now=DateTimeOffset.FromUnixTimeMilliseconds(AccountStateSnapshot.Number(data,"serverTime"));var applied=AccountStateSnapshot.Number(data,"appliedEventId");var latest=AccountStateSnapshot.Number(data,"latestEventId");if(applied>latest)throw new FormatException();
   var service=now.AddHours(5);var day=new DateTimeOffset(service.Year,service.Month,service.Day,0,0,0,TimeSpan.Zero).AddHours(-5);var month=new DateTimeOffset(service.Year,service.Month,1,0,0,0,TimeSpan.Zero).AddHours(-5);int dayIndex=(int)(day-month).TotalDays;
   var systems=RecruitmentJson.Array(data,"systems");if(systems.Count!=2)throw new FormatException();RecurringContract.Unique(systems,"system");foreach(JObject system in systems){var name=RecurringContract.One(system,"system","QUESTS","PASS50");var state=RecurringContract.One(system,"status","ACTIVE","NOT_CONFIGURED_FOR_CURRENT_PERIOD");var policy=RecruitmentJson.NullableString(system,"policyId");var rows=RecruitmentJson.Array(system,"objectives");if(state!="ACTIVE"){if(policy!=null||rows.Count!=0)throw new FormatException();continue;}MonthlyAttendanceContract.Id(system,"policyId");if(rows.Count!=(name=="QUESTS"?5:6))throw new FormatException();RecurringContract.Unique(rows,"objectiveId");foreach(JObject row in rows){var id=RecurringContract.One(row,"objectiveId","D1","D2","D3","W1","W2","W3");if(name=="QUESTS"&&id=="D1")throw new FormatException();var weekly=id.StartsWith("W");var login=id=="D1"||id=="W1";var expectedMetric=login?"login":id=="W3"?"waves":"ends";
    if(GameApiJson.String(row,"frequency")!=(weekly?"WEEKLY":"DAILY")||GameApiJson.String(row,"metric")!=expectedMetric||GameApiJson.String(row,"calendar")!=(weekly?name=="QUESTS"?"MONDAY_04_KST":"SEASON_RELATIVE_7_DAYS":"DAILY_04_KST")||GameApiJson.String(row,"currentScope")!=(login?"SERVER_RECORDED_LOGIN":"RECORDED_ELIGIBLE_OWNER_FINISH"))throw new FormatException();
    MonthlyAttendanceContract.Range(row,"target",1,int.MaxValue);AccountStateSnapshot.Number(row,"xp");RecurringContract.Rewards(RecruitmentJson.Array(row,"rewards"));var award=RecruitmentJson.NullableString(row,"awardId");if(award!=null)MonthlyAttendanceContract.Id(row,"awardId");var status=RecurringContract.One(row,"status","NOT_SCHEDULED","IN_PROGRESS","UNKNOWN","SYNC_PENDING","EARNED","CLAIMED","XP_APPLIED");var reached=GameApiJson.Boolean(row,"observedTargetReached");var pending=GameApiJson.Boolean(row,"syncPending");var reasons=RecruitmentJson.Array(row,"unknownReasons");foreach(var reason in reasons)if(reason.Type!=JTokenType.String)throw new FormatException();
    var scheduled=!(name=="PASS50"&&weekly&&dayIndex>=28);if(!scheduled){foreach(var field in new[]{"periodId","periodStartAt","periodEndAt","current","observedCurrent","awardId"})if(row[field]?.Type!=JTokenType.Null)throw new FormatException();if(status!="NOT_SCHEDULED"||(string)row["coverage"]!="NOT_SCHEDULED"||reached||pending||reasons.Count!=0)throw new FormatException();continue;}
    var start=weekly?name=="QUESTS"?day.AddDays(-(((int)service.DayOfWeek+6)%7)):month.AddDays((dayIndex/7)*7):day;var end=start.AddDays(weekly?7:1);var period=weekly?name=="QUESTS"?"W:"+start.ToUnixTimeMilliseconds():"W:"+month.ToUnixTimeMilliseconds()+":"+dayIndex/7:"D:"+start.ToUnixTimeMilliseconds();
    if(AccountStateSnapshot.Number(row,"periodStartAt")!=start.ToUnixTimeMilliseconds()||AccountStateSnapshot.Number(row,"periodEndAt")!=end.ToUnixTimeMilliseconds()||GameApiJson.String(row,"periodId")!=period)throw new FormatException();var observed=AccountStateSnapshot.Number(row,"observedCurrent");if(reached!=(observed>=(long)row["target"]))throw new FormatException();
    if(login){if(GameApiJson.String(row,"coverage")!="COMPLETE_FOR_RECORDED_LOGIN"||AccountStateSnapshot.Number(row,"current")!=observed||reasons.Count!=0)throw new FormatException();}else if(GameApiJson.String(row,"coverage")!="PARTIAL_UNKNOWN"||row["current"]?.Type!=JTokenType.Null||!reasons.Any(r=>(string)r=="COOPERATIVE_PARTICIPANT_PRODUCER_MISSING"))throw new FormatException();
    if(award!=null){if(status!=(name=="PASS50"?"XP_APPLIED":status=="CLAIMED"?"CLAIMED":"EARNED"))throw new FormatException();}else if(status!=(reached?"SYNC_PENDING":login?"IN_PROGRESS":"UNKNOWN")||reached&&!pending)throw new FormatException();
   }}
  }
  public static string ProgressText(JObject row){if((string)row["status"]=="NOT_SCHEDULED")return "이번 기간 미운영";return (string)row["metric"]=="login"?"접속 기록 "+(long)row["current"]+" / "+(long)row["target"]:"전체 진행 확인 중 · 확인된 기록 "+(long)row["observedCurrent"]+" (목표 "+(long)row["target"]+")";}
  public static string StatusText(JObject row){var s=(string)row["status"];return s=="CLAIMED"?"수령 완료":s=="EARNED"?"받기":s=="XP_APPLIED"?"XP 반영 완료":s=="SYNC_PENDING"?"진행 반영 대기":s=="NOT_SCHEDULED"?"미운영":s=="IN_PROGRESS"?"진행 중":"진행 확인 중";}
 }
}
